                    if route_load(routes[r2]) + dem_c > capacity:
                        continue
                    for pos in range(len(routes[r2]) + 1):
                        new_routes = []
                        for rr in routes:
                            new_routes.append(rr[:])
                        del new_routes[r1][i]
                        new_routes[r2].insert(pos, c)
                        if len(new_routes[r1]) == 0:
                            # remove empty route
                            new_routes.pop(r1)
                        new_cost = total_cost(new_routes)
                        if new_cost + 1e-12 < base_cost:
                            routes = new_routes
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break

        if improved:
            continue

        # swap
        for r1 in range(len(routes)):
            if improved:
                break
            for i in range(len(routes[r1])):
                c1 = routes[r1][i]
                d1 = demand_of(c1)
                for r2 in range(r1 + 1, len(routes)):
                    for j in range(len(routes[r2])):
                        c2 = routes[r2][j]
                        d2 = demand_of(c2)
                        load1 = route_load(routes[r1]) - d1 + d2
                        load2 = route_load(routes[r2]) - d2 + d1
                        if load1 > capacity or load2 > capacity:
                            continue
                        new_routes = []
                        for rr in routes:
                            new_routes.append(rr[:])
                        new_routes[r1][i], new_routes[r2][j] = new_routes[r2][j], new_routes[r1][i]
                        new_cost = total_cost(new_routes)
                        if new_cost + 1e-12 < base_cost:
                            routes = new_routes
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break

    # Final cleanup: remove any empty routes and ensure all customers are present exactly once.
    cleaned = []
    seen = {}
    for r in routes:
        rr = []
        for c in r:
            if c == depot:
                continue
            if c not in seen:
                seen[c] = True
                rr.append(c)
        if rr:
            cleaned.append(rr)

    # Add missing customers if any
    for c in customers:
        if c == depot:
            continue
        if c not in seen:
            placed = False
            best_r = None
            best_pos = None
            best_delta = None
            for r_idx in range(len(cleaned)):
                if route_load(cleaned[r_idx]) + demand_of(c) > capacity:
                    continue
                r = cleaned[r_idx]
                for pos in range(len(r) + 1):
                    left = depot if pos == 0 else r[pos - 1]
                    right = depot if pos == len(r) else r[pos]
                    delta = dist(left, c) + dist(c, right) - dist(left, right)
                    if best_delta is None or delta < best_delta:
                        best_delta = delta
                        best_r = r_idx
                        best_pos = pos
            if best_r is not None:
                cleaned[best_r].insert(best_pos, c)
                seen[c] = True
                placed = True
            if not placed:
                cleaned.append([c])
                seen[c] = True

    return cleaned
